1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.Locale;
4	import java.util.Map;
5	
6	/**
7	 * Shared normalization for the owner postal address. The canonical stored and returned form is
8	 * trimmed, has internal whitespace collapsed to single spaces, is upper-cased and has common
9	 * street-type abbreviations expanded ({@code ST -> STREET}, {@code RD -> ROAD},
10	 * {@code AVE -> AVENUE}). Applied when an owner is created so the stored address, the required-field
11	 * check and every household comparison (duplicate detection and the shared household id) all use the
12	 * same form.
13	 */
14	final class OwnerAddress {
15	
16	    /** Whole-token street-type abbreviations expanded to their full form. */
17	    private static final Map<String, String> ABBREVIATIONS = Map.of(
18	            "ST", "STREET",
19	            "RD", "ROAD",
20	            "AVE", "AVENUE");
21	
22	    private OwnerAddress() {
23	    }
24	
25	    /**
26	     * @return the normalized address (trimmed, whitespace-collapsed, upper-cased, abbreviations
27	     * expanded), or an empty string when {@code address} is {@code null} or blank after trimming.
28	     */
29	    static String normalize(String address) {
30	        if (address == null) {
31	            return "";
32	        }
33	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
34	        if (collapsed.isEmpty()) {
35	            return "";
36	        }
37	        String[] tokens = collapsed.split(" ");
38	        StringBuilder sb = new StringBuilder(collapsed.length());
39	        for (int i = 0; i < tokens.length; i++) {
40	            if (i > 0) {
41	                sb.append(' ');
42	            }
43	            sb.append(ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
44	        }
45	        return sb.toString();
46	    }
47	}
