1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.nio.charset.StandardCharsets;
4	import java.security.MessageDigest;
5	import java.security.NoSuchAlgorithmException;
6	
7	/**
8	 * Household identity for pet owners. Two owners belong to the same household when they share a last
9	 * name (compared case-insensitively with collapsed whitespace) and a postcode. The
10	 * {@link #id(String, String)} value is a stable identifier derived purely from those two fields, so
11	 * every owner in a household returns the same {@code householdId} without any stored state. Because
12	 * the household is keyed on those fields alone, two owners sharing last name and postcode are the
13	 * same household automatically — there is no stored link. Used as one component of the owner
14	 * {@link OwnerIdentity} key, by {@link RequireUniqueIdentity} to detect a household duplicate,
15	 * by {@link CountHouseholdMembers} to size the household and by the owner mapper to expose the
16	 * identifier on responses.
17	 */
18	public final class Household {
19	
20	    private Household() {
21	    }
22	
23	    /** Trim, collapse internal whitespace and lower-case for case-insensitive comparison. */
24	    public static String normalize(String value) {
25	        if (value == null) {
26	            return "";
27	        }
28	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
29	    }
30	
31	    /**
32	     * A stable shared identifier for the household of an owner with the given last name and postcode:
33	     * the first 12 hex characters of the SHA-256 digest over {@code normalizedLastName + '|' +
34	     * postcode}. Derived purely from those two fields, so owners in the same household get the same
35	     * value.
36	     */
37	    public static String id(String lastName, String postcode) {
38	        String key = normalize(lastName) + "|" + (postcode == null ? "" : postcode);
39	        try {
40	            byte[] digest = MessageDigest.getInstance("SHA-256").digest(key.getBytes(StandardCharsets.UTF_8));
41	            StringBuilder sb = new StringBuilder(12);
42	            for (int i = 0; i < 6; i++) {
43	                sb.append(String.format("%02X", digest[i]));
44	            }
45	            return sb.toString();
46	        }
47	        catch (NoSuchAlgorithmException e) {
48	            throw new IllegalStateException("SHA-256 not available", e);
49	        }
50	    }
51	}
