1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.Map;
4	import java.util.Set;
5	
6	/**
7	 * Locality (canonical region) for pet owners. For a created owner the region is read straight off
8	 * the REGION prefix of its {@code customerCode} (see {@link AssignCustomerCode}), so the locality
9	 * shown on responses is exactly the region baked into the region-and-hash identity. When no such
10	 * code is present (e.g. legacy owners with no customer code) it falls back to resolving the region
11	 * from the owner's postcode first, using fixed inclusive postcode ranges: {@code NSW 2000-2099},
12	 * {@code VIC 3000-3099}, {@code QLD 4000-4099}; when the postcode is absent or falls in no known
13	 * range, it falls back to a fixed city-to-region table: {@code Sydney -> NSW},
14	 * {@code Melbourne -> VIC}, {@code Brisbane -> QLD}. Anything unresolved yields {@code UNKNOWN}.
15	 * Preferring the postcode returns the same region for known cities but disambiguates cities that
16	 * share a name. Derived purely from the owner's own state, so it carries no stored data and is
17	 * seed-independent. Used by the owner mapper to expose {@code locality} on responses.
18	 */
19	public final class Locality {
20	
21	    /** City -> canonical region. Fixed, pinned reference data. */
22	    private static final Map<String, String> CITY_REGION = Map.of(
23	            "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
24	
25	    /** The canonical regions a customer code may carry, used to recognise its REGION prefix. */
26	    private static final Set<String> KNOWN_REGIONS = Set.of("NSW", "VIC", "QLD", "UNKNOWN");
27	
28	    /** Region -> inclusive 4-digit postcode range {low, high}. Fixed, pinned reference data. */
29	    private static final Map<String, int[]> REGION_RANGES = Map.of(
30	            "NSW", new int[] {2000, 2099},
31	            "VIC", new int[] {3000, 3099},
32	            "QLD", new int[] {4000, 4099});
33	
34	    private Locality() {
35	    }
36	
37	    /**
38	     * The canonical region for an owner, read from the REGION prefix of its {@code customerCode}
39	     * when present and falling back to the postcode-then-city derivation otherwise. This is the
40	     * mapping the owner mapper uses so the exposed locality matches the region-and-hash identity.
41	     */
42	    public static String of(String customerCode, String postcode, String city) {
43	        String fromCode = fromCustomerCode(customerCode);
44	        return fromCode != null ? fromCode : of(postcode, city);
45	    }
46	
47	    /**
48	     * The canonical region for the given owner, resolved from the postcode first and falling back
49	     * to the city when the postcode is absent or in no known range. Yields {@code UNKNOWN} when
50	     * neither resolves.
51	     */
52	    public static String of(String postcode, String city) {
53	        String byPostcode = fromPostcode(postcode);
54	        return byPostcode != null ? byPostcode : of(city);
55	    }
56	
57	    /**
58	     * The canonical region for the given city, or {@code UNKNOWN} when the city is not in the
59	     * fixed table.
60	     */
61	    public static String of(String city) {
62	        return CITY_REGION.getOrDefault(city, "UNKNOWN");
63	    }
64	
65	    /** The REGION prefix of a {@code <REGION>-<HASH8>} customer code, or {@code null} when the code
66	     *  is absent or does not carry a recognised region. */
67	    private static String fromCustomerCode(String customerCode) {
68	        if (customerCode == null) {
69	            return null;
70	        }
71	        int dash = customerCode.indexOf('-');
72	        if (dash <= 0) {
73	            return null;
74	        }
75	        String region = customerCode.substring(0, dash);
76	        return KNOWN_REGIONS.contains(region) ? region : null;
77	    }
78	
79	    /** The region whose range contains the postcode, or {@code null} when absent or out of range. */
80	    private static String fromPostcode(String postcode) {
81	        if (postcode == null || !postcode.matches("[0-9]{4}")) {
82	            return null;
83	        }
84	        int value = Integer.parseInt(postcode);
85	        for (Map.Entry<String, int[]> entry : REGION_RANGES.entrySet()) {
86	            int[] range = entry.getValue();
87	            if (value >= range[0] && value <= range[1]) {
88	                return entry.getKey();
89	            }
90	        }
91	        return null;
92	    }
93	}
