27	/**
28	 * Simple JavaBean domain object representing an owner.
29	 *
30	 * @author Ken Krebs
31	 * @author Juergen Hoeller
32	 * @author Sam Brannen
33	 * @author Michael Isvy
34	 */
35	@Entity
36	@Table(name = "owners")
37	public class Owner extends Person {
38	    @Column(name = "address")
39	    @NotEmpty
40	    private String address;
41	
42	    @Column(name = "city")
43	    @NotEmpty
44	    private String city;
45	
46	    @Column(name = "telephone")
47	    @NotEmpty
48	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be in E.164 form")
49	    private String telephone;
50	
51	    @Column(name = "email")
52	    private String email;
53	
54	    @Column(name = "postcode")
55	    private String postcode;
56	
57	    @Column(name = "registration_date", columnDefinition = "DATE")
58	    private LocalDate registrationDate;
59	
60	    @Column(name = "birth_date", columnDefinition = "DATE")
61	    private LocalDate birthDate;
62	
63	    @Column(name = "customer_code")
64	    private String customerCode;
65	
66	    @Column(name = "namesake_count")
67	    private Integer namesakeCount;
68	
69	    @Column(name = "household_size")
70	    private Integer householdSize;
71	
72	    @Column(name = "bulk_signup_warning")
73	    private Boolean bulkSignupWarning;
74	
75	    @Column(name = "possible_duplicate")
76	    private Boolean possibleDuplicate;
77	
78	    @Column(name = "possible_duplicate_of")
79	    private Integer possibleDuplicateOf;
80	
81	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
82	    private Set<Pet> pets;
83	
84	    public String getAddress() {
85	        return this.address;
86	    }
87	
88	    public void setAddress(String address) {
89	        this.address = address;
90	    }
91	
92	    public String getCity() {
93	        return this.city;
94	    }
95	
96	    public void setCity(String city) {
97	        this.city = city;
98	    }
99	
100	    public String getTelephone() {
101	        return this.telephone;
102	    }
103	
104	    public void setTelephone(String telephone) {
105	        this.telephone = telephone;
106	    }
107	
108	    public String getEmail() {
109	        return this.email;
110	    }
111	
112	    public void setEmail(String email) {
113	        this.email = email;
114	    }
115	
116	    public String getPostcode() {
117	        return this.postcode;
118	    }
119	
120	    public void setPostcode(String postcode) {
121	        this.postcode = postcode;
122	    }
123	
124	    public LocalDate getRegistrationDate() {
125	        return this.registrationDate;
126	    }
127	
128	    public void setRegistrationDate(LocalDate registrationDate) {
129	        this.registrationDate = registrationDate;
130	    }
131	
132	    public LocalDate getBirthDate() {
133	        return this.birthDate;
134	    }
135	
136	    public void setBirthDate(LocalDate birthDate) {
137	        this.birthDate = birthDate;
138	    }
139	
140	    public String getCustomerCode() {
141	        return this.customerCode;
142	    }
143	
144	    public void setCustomerCode(String customerCode) {
145	        this.customerCode = customerCode;
146	    }
147	
148	    public Integer getNamesakeCount() {
149	        return this.namesakeCount;
150	    }
151	
152	    public void setNamesakeCount(Integer namesakeCount) {
153	        this.namesakeCount = namesakeCount;
154	    }
155	
156	    public Integer getHouseholdSize() {
157	        return this.householdSize;
158	    }
159	
160	    public void setHouseholdSize(Integer householdSize) {
161	        this.householdSize = householdSize;
162	    }
163	
164	    public Boolean getBulkSignupWarning() {
165	        return this.bulkSignupWarning;
166	    }
167	
168	    public void setBulkSignupWarning(Boolean bulkSignupWarning) {
169	        this.bulkSignupWarning = bulkSignupWarning;
170	    }
171	
172	    public Boolean getPossibleDuplicate() {
173	        return this.possibleDuplicate;
174	    }
175	
176	    public void setPossibleDuplicate(Boolean possibleDuplicate) {
177	        this.possibleDuplicate = possibleDuplicate;
178	    }
179	
180	    public Integer getPossibleDuplicateOf() {
181	        return this.possibleDuplicateOf;
182	    }
183	
184	    public void setPossibleDuplicateOf(Integer possibleDuplicateOf) {
185	        this.possibleDuplicateOf = possibleDuplicateOf;
186	    }
187	
188	    protected Set<Pet> getPetsInternal() {
189	        if (this.pets == null) {
190	            this.pets = new HashSet<>();
191	        }
192	        return this.pets;
193	    }
194	
195	    protected void setPetsInternal(Set<Pet> pets) {
196	        this.pets = pets;
197	    }
198	
199	    public List<Pet> getPets() {
200	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
201	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
202	        return Collections.unmodifiableList(sortedPets);
203	    }
204	
205	    public void setPets(List<Pet> pets) {
206	        this.pets = new HashSet<>(pets);
207	    }
208	
209	    public void addPet(Pet pet) {
210	        getPetsInternal().add(pet);
211	        pet.setOwner(this);
212	    }
213	
214	    /**
215	     * Return the Pet with the given name, or null if none found for this Owner.
216	     *
217	     * @param name to test
218	     * @return true if pet name is already in use
219	     */
220	    public Pet getPet(String name) {
221	        return getPet(name, false);
222	    }
223	
224	    /**
225	     * Return the Pet with the given name, or null if none found for this Owner.
226	     *
227	     * @param name to test
228	     * @return true if pet name is already in use
229	     */
230	    public Pet getPet(String name, boolean ignoreNew) {
231	        name = name.toLowerCase();
232	        for (Pet pet : getPetsInternal()) {
233	            if (!ignoreNew || !pet.isNew()) {
234	                String compName = pet.getName();
235	                compName = compName.toLowerCase();
236	                if (compName.equals(name)) {
237	                    return pet;
238	                }
239	            }
240	        }
241	        return null;
242	    }
243	
244	    public Pet getPet(Integer petId) {
245	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
246	    }
247	
248	    @Override
249	    public String toString() {
250	        return new ToStringCreator(this)
251	
252	            .append("id", this.getId())
253	            .append("new", this.isNew())
254	            .append("lastName", this.getLastName())
255	            .append("firstName", this.getFirstName())
256	            .append("address", this.address)
257	            .append("city", this.city)
258	            .append("telephone", this.telephone)
259	            .toString();
260	    }
261	}
