3	import org.jspecify.annotations.NonNull;
4	import org.mapstruct.Mapper;
5	import org.mapstruct.Mapping;
6	import org.springframework.data.domain.Page;
7	import org.springframework.samples.petclinic.model.Owner;
8	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
9	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
10	import org.springframework.samples.petclinic.rest.dto.OwnerPageDto;
11	
12	import java.util.Collection;
13	import java.util.List;
14	
15	/**
16	 * Maps Owner & OwnerDto using Mapstruct
17	 */
18	@Mapper(uses = PetMapper.class)
19	public interface OwnerMapper {
20	
21	    @Mapping(target = "displayName",
22	            expression = "java(owner.getLastName() + \", \" + owner.getFirstName())")
23	    @Mapping(target = "initials",
24	            expression = "java(owner.getFirstName().substring(0, 1).toUpperCase() + \".\" + owner.getLastName().substring(0, 1).toUpperCase() + \".\")")
25	    @Mapping(target = "telephoneDisplay",
26	            expression = "java(org.springframework.samples.petclinic.rest.function.owner.TelephoneDisplay.of(owner.getTelephone()))")
27	    @Mapping(target = "householdId",
28	            expression = "java(org.springframework.samples.petclinic.rest.function.owner.Household.id(owner.getLastName(), owner.getPostcode()))")
29	    @Mapping(target = "identityKey",
30	            expression = "java(org.springframework.samples.petclinic.rest.function.owner.OwnerIdentity.key(owner.getTelephone(), owner.getEmail(), owner.getLastName(), owner.getPostcode()))")
31	    @Mapping(target = "membershipNumber",
32	            expression = "java(org.springframework.samples.petclinic.rest.function.owner.MembershipNumber.of(owner.getCustomerCode(), owner.getRegistrationDate()))")
33	    @Mapping(target = "checkDigit",
34	            expression = "java(org.springframework.samples.petclinic.rest.function.owner.CheckDigit.of(owner.getCustomerCode()))")
35	    @Mapping(target = "membershipPoints",
36	            expression = "java(org.springframework.samples.petclinic.rest.function.owner.MembershipPoints.of(owner.getNamesakeCount(), owner.getEmail(), owner.getHouseholdSize(), owner.getRegistrationDate()))")
37	    @Mapping(target = "membershipLevel",
38	            expression = "java(org.springframework.samples.petclinic.rest.function.owner.MembershipLevel.of(org.springframework.samples.petclinic.rest.function.owner.MembershipPoints.of(owner.getNamesakeCount(), owner.getEmail(), owner.getHouseholdSize(), owner.getRegistrationDate())))")
39	    @Mapping(target = "locality",
40	            expression = "java(org.springframework.samples.petclinic.rest.function.owner.Locality.of(owner.getCustomerCode(), owner.getPostcode(), owner.getCity()))")
41	    @Mapping(target = "timezone",
42	            expression = "java(org.springframework.samples.petclinic.rest.function.owner.Timezone.of(owner.getCustomerCode(), owner.getPostcode(), owner.getCity()))")
43	    @Mapping(target = "contactPreference",
44	            expression = "java(org.springframework.samples.petclinic.rest.function.owner.ContactPreference.of(owner.getEmail()))")
45	    @Mapping(target = "ageBand",
46	            expression = "java(org.springframework.samples.petclinic.rest.function.owner.AgeBand.of(owner.getBirthDate(), owner.getRegistrationDate()))")
47	    OwnerDto toOwnerDto(Owner owner);
48	
49	    Owner toOwner(OwnerDto ownerDto);
50	
51	    @Mapping(target = "id", ignore = true)
52	    @Mapping(target = "pets", ignore = true)
53	    Owner toOwner(OwnerFieldsDto ownerDto);
54	
55	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
56	
57	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
58	
59	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
60	        OwnerPageDto ownerPageDto = new OwnerPageDto();
61	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
62	        ownerPageDto.setPage(ownerPage.getNumber());
63	        ownerPageDto.setSize(ownerPage.getSize());
64	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
65	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
66	        return ownerPageDto;
67	    }
68	}
