3	import java.util.Locale;
4	
5	import org.springframework.samples.petclinic.rest.escalation.InvalidTelephoneException;
6	
7	/**
8	 * The single derived identity of a pet owner. The {@code identityKey} is
9	 * {@code normalizedTelephone + '|' + (email or empty) + '|' + householdId}, where the telephone is
10	 * canonical E.164 form, the email is trimmed and lower-cased (or empty when absent) and the household
11	 * id is {@link Household#id(String, String)} over the last name and postcode.
12	 *
13	 * <p>Because the telephone is part of the key, two members of the same household (same householdId)
14	 * with different telephones have different identity keys and are both allowed; only owners that are
15	 * the same contact collide. Duplicate detection compares the {@link #contactKey(String, String)} —
16	 * the telephone-and-email prefix of the key that is what actually identifies one owner, so two owners
17	 * in the same household with different telephones (or emails) are distinct and both persist.
18	 *
19	 * <p>Used by {@link RequireUniqueIdentity} to reject a collision and by the owner mapper to expose
20	 * the full key on responses.
21	 */
22	public final class OwnerIdentity {
23	
24	    private OwnerIdentity() {
25	    }
26	
27	    /** The full identity key for an owner with the given raw fields, as exposed on responses. Fields
28	     *  are normalized here so the same value is produced whether they come from a freshly-validated
29	     *  request or a stored owner. */
30	    public static String key(String telephone, String email, String lastName, String postcode) {
31	        return contactKey(telephone, email) + "|" + Household.id(lastName, postcode);
32	    }
33	
34	    /** The telephone-and-email prefix of the identity key, identifying a single contact. Two owners
35	     *  are duplicates when their contact keys are equal. */
36	    public static String contactKey(String telephone, String email) {
37	        return normalizedTelephone(telephone) + "|" + normalizeEmail(email);
38	    }
39	
40	    /** The telephone in canonical E.164 form, or the raw value (or empty when {@code null}) when it
41	     *  cannot be normalized. Shared so the customer-code hash and the identity key normalize the
42	     *  telephone the same way. */
43	    public static String normalizedTelephone(String telephone) {
44	        try {
45	            return OwnerTelephone.toE164(telephone);
46	        }
47	        catch (InvalidTelephoneException ex) {
48	            return telephone == null ? "" : telephone;
49	        }
50	    }
51	
52	    private static String normalizeEmail(String email) {
53	        if (email == null || email.isBlank()) {
54	            return "";
55	        }
56	        return email.trim().toLowerCase(Locale.ROOT);
57	    }
58	}
